(() => {
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v??'').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const icons={home:'<path d="m3 10 7-7 7 7v9H5v-9"/><path d="M8 19v-7h4v7"/>',book:'<path d="M10 5v15M3 4c3-1 5-1 7 1 2-2 4-2 7-1v14c-3-1-5-1-7 1-2-2-4-2-7-1z"/>',quiz:'<rect x="4" y="3" width="13" height="17" rx="3"/><path d="m7 8 1 1 2-2m-3 6 1 1 2-2m2-4h2m-2 5h2"/>',headphones:'<path d="M3 12V9a7 7 0 0 1 14 0v3"/><rect x="2" y="10" width="4" height="8" rx="2"/><rect x="14" y="10" width="4" height="8" rx="2"/>',chart:'<path d="M3 3v16h15M7 15v-4m4 4V7m4 8V4"/>',source:'<path d="M5 3h8l4 4v13H5zM12 3v5h5M8 12h6m-6 4h6"/>',clock:'<circle cx="10" cy="10" r="8"/><path d="M10 5v5l3 2"/>',check:'<path d="m4 10 4 4 8-9"/>',spark:'<path d="m10 2 2 6 6 2-6 2-2 6-2-6-6-2 6-2zM17 2v4m-2-2h4"/>',leaf:'<path d="M4 16C-1 6 9 2 18 3c1 9-3 16-11 14M3 19 14 7"/>',lock:'<rect x="4" y="9" width="12" height="10" rx="3"/><path d="M6 9V6a4 4 0 0 1 8 0v3M10 13v2"/>',chevron:'<path d="m8 5 5 5-5 5"/>',back:'<path d="m12 4-6 6 6 6"/>',close:'<path d="m5 5 10 10M15 5 5 15"/>',menu:'<path d="M3 5h14M3 10h14M3 15h14"/>',volume:'<path d="M3 8h4l5-4v12l-5-4H3zM15 6a6 6 0 0 1 0 8"/>',focus:'<path d="M7 3H3v4m10-4h4v4M3 13v4h4m10-4v4h-4"/><circle cx="10" cy="10" r="2"/>',trophy:'<path d="M6 3h8v6a4 4 0 0 1-8 0zM6 5H3v3c0 2 1 3 4 3m7-6h3v3c0 2-1 3-4 3M10 13v4m-4 2h8"/>',refresh:'<path d="M17 8a7 7 0 0 0-12-4L2 7m0-4v4h4m-3 6a7 7 0 0 0 12 4l3-3m0 4v-4h-4"/>',download:'<path d="M10 2v11m-4-4 4 4 4-4M3 14v4h14v-4"/>',upload:'<path d="M10 14V3m-4 4 4-4 4 4M3 14v4h14v-4"/>',warning:'<path d="m10 2 9 16H1zM10 7v4m0 3v1"/>',road:'<path d="m5 2-3 17M15 2l3 17M10 3v3m0 3v3m0 3v3"/>',play:'<path d="m7 3 10 7-10 7z"/>',stop:'<rect x="4" y="4" width="12" height="12" rx="2"/>',heart:'<path d="M10 17 3 10C-2 3 8 0 10 6 12 0 22 3 17 10z"/>',settings:'<path d="M3 5h14M3 10h14M3 15h14"/><circle cx="7" cy="5" r="2" fill="white"/><circle cx="13" cy="10" r="2" fill="white"/><circle cx="8" cy="15" r="2" fill="white"/>'};
const icon = name => `<svg class="icon" viewBox="0 0 20 22" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const STORE='drive-b-progress-v1';
const defaults=()=>({version:1,completed:[],lessonSteps:{},lastLesson:1,goal:10,region:'Flanders',voiceMode:'nl-en',results:[],mistakes:[],correctCounts:{},focus:false});
let state=defaults(),storageOK=true;
function validProgress(x){return x && x.version===1 && Array.isArray(x.completed) && x.completed.every(n=>Number.isInteger(n)&&n>=1&&n<=31)&&x.lessonSteps&&typeof x.lessonSteps==='object'&&!Array.isArray(x.lessonSteps)&&Object.entries(x.lessonSteps).every(([k,v])=>/^([1-9]|[12][0-9]|3[01])$/.test(k)&&Number.isInteger(v)&&v>=0&&v<=3)&&Array.isArray(x.results)&&x.results.length<=100&&x.results.every(r=>r&&Number.isFinite(r.score)&&Number.isInteger(r.total)&&r.total>0&&r.total<=50&&r.score>=0&&r.score<=r.total&&Number.isInteger(r.correct)&&r.correct>=0&&r.correct<=r.total&&typeof r.date==='string'&&Number.isFinite(Date.parse(r.date))&&['quiz','exam','text-exam'].includes(r.mode))&&Array.isArray(x.mistakes)&&x.mistakes.every(id=>typeof id==='string'&&/^q\d{3}$/.test(id))&&x.correctCounts&&typeof x.correctCounts==='object'&&Object.values(x.correctCounts).every(n=>Number.isInteger(n)&&n>=0)&&[5,10,15,20].includes(x.goal)&&['Flanders','Brussels','Wallonia'].includes(x.region)&&['nl-en','en'].includes(x.voiceMode)&&Number.isInteger(x.lastLesson)&&x.lastLesson>=1&&x.lastLesson<=31;}
try{const raw=localStorage.getItem(STORE);if(raw){const x=JSON.parse(raw);if(validProgress(x))state={...state,...x,completed:[...new Set(x.completed)]};else storageOK=false;}}catch(e){storageOK=false;}
let quiz=null,check=null,session=null,breakDismissed=false,activeUtterance=null,audioToken=0,audioWatchdog=null,timer=null,audioPlaying=false,leaving=false;
const COURSE=window.DRIVE_COURSE;
const QUESTIONS=window.DRIVE_QUESTIONS;
if(!COURSE||!QUESTIONS){$('#app').innerHTML='<main><h1>The course could not load.</h1><p>Refresh this page to try again. Your saved progress stays in your browser.</p></main>';return;}
const lessons=COURSE.lessons,chapters=COURSE.chapters,sources=COURSE.sources;
const assetMeta=window.DRIVE_ASSETS||[];
const getLesson=id=>lessons.find(l=>l.id===Number(id));
const getChapter=id=>chapters.find(c=>c.id===id);
const percentage=()=>Math.round(state.completed.length/lessons.length*100);
const nextLesson=()=>!state.completed.includes(state.lastLesson)?getLesson(state.lastLesson):lessons.find(l=>!state.completed.includes(l.id))||lessons[0];
const source=id=>sources.find(s=>s.id===id)||sources[0];
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('Your browser could not save progress. Keep this tab open or export it.');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function stopAudio(){audioToken++;clearTimeout(audioWatchdog);activeUtterance=null;audioPlaying=false;if('speechSynthesis' in window)speechSynthesis.cancel();}
function stopTimer(){clearInterval(timer);timer=null;}
function imageHTML(file,css='',caption=false){if(!file)return '';const m=assetMeta.find(x=>x.file===file);return `<figure class="lesson-photo ${css}"><img src="assets/${esc(file)}" alt="${esc(m?.label||file.replace(/[-.]/g,' '))}" loading="lazy">${caption?`<figcaption>${esc(m?.label||'SourceBook illustration')} · Book p. ${m?.page||'—'}</figcaption>`:''}</figure>`;}
function ring(p){return `<div class="progress-ring" style="--angle:${p*3.6}deg" role="img" aria-label="${p}% of lessons completed"><div class="ring-value"><strong>${p}%</strong><span>completed</span></div></div>`;}
function track(p){return `<div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p}" aria-label="Learning progress"><span style="width:${p}%"></span></div>`;}
function intro(title,description,right=''){return `<div class="page-intro"><div><h1>${title}</h1><p>${description}</p></div>${right}</div>`;}
function chapterCard(c){const n=c.lessons.filter(id=>state.completed.includes(id)).length;return `<a class="chapter-card card" href="#chapter/${c.id}"><div class="chapter-image ${c.id==='passing'?'sign-image':''}"><img src="assets/${c.image}" alt="${esc(assetMeta.find(x=>x.file===c.image)?.label||c.title)}" loading="lazy"><span class="chapter-number">${c.number}</span></div><div class="chapter-body"><h3>${c.title}</h3><p>${c.description}</p><div class="chapter-bottom"><span>${c.lessons.length} short lessons</span><span>${n}/${c.lessons.length} complete</span></div>${track(Math.round(n/c.lessons.length*100))}</div></a>`;}
const route=()=>location.hash.slice(1)||'home';
function layout(content,active='home',label='Overview'){
 const nav=[['home','home','My dashboard'],['learn','book','Learning path'],['practice','quiz','Practice quizzes'],['exam','headphones','Exam simulator'],['progress','chart','My progress'],['sources','source','Book & sources']];
 return `<div class="app-layout ${state.focus&&route().startsWith('lesson/')?'focus':''}"><aside class="sidebar" aria-label="Main navigation"><a class="brand" href="#home"><span class="brand-mark">B</span><span class="brand-name">drive b<small>THEORY B · BELGIUM</small></span></a><div class="nav-label">YOUR LEARNING SPACE</div><nav class="nav">${nav.map(([id,ic,text])=>`<a href="#${id}" ${active===id?'class="active" aria-current="page"':''}>${icon(ic)}<span>${text}</span>${id==='practice'&&state.mistakes.length?`<span class="nav-count">${state.mistakes.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('leaf')}<h3>Small steps count.</h3><p>Five focused minutes is progress. Pick a pace that works today.</p></div><div class="sidebar-footer">${icon('lock')}<span>Just you & your next milestone</span></div></div></aside><div class="content-wrap"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><span>Your space</span><span>/</span><strong>${label}</strong></div><div class="top-actions">${session?`<span class="active-session">${icon('clock')}${state.goal}-minute session</span>`:''}<button class="button ghost region-chip" data-action="settings" aria-label="Study settings, current region ${esc(state.region)}"><span class="flag" aria-hidden="true"></span>${esc(state.region)} · B${icon('settings')}</button><span class="avatar" aria-label="Personal study space">ME</span></div></header><main id="main" tabindex="-1">${!storageOK?'<div class="storage-warning" role="status">Browser storage is unavailable or the saved file could not be read. Your work is kept in this tab. You can export your progress from My progress.</div>':''}${session&&!breakDismissed&&Date.now()-session.start>=session.duration?`<div class="break-banner">${icon('leaf')}<p>Your ${state.goal}-minute session is complete. This is a good moment for a break.</p><button class="button secondary small" data-action="dismiss-break">Keep going</button><a href="#home" class="text-link">Take a break</a></div>`:''}${content}<footer class="footer-note"><span>${icon('lock')} Progress saved on this browser · No account or database</span><span>Rules checked 1 Oct 2026 · <a href="#sources">See sources & corrections</a></span></footer></main></div></div>`;
}
function home(){const l=nextLesson(),c=getChapter(l.chapter),p=percentage();return layout(`${intro('Let’s make some progress.','Your next step is ready. Take it at your own pace.',`<span class="pill">${icon('road')}Flemish Theory B</span>`)}<div class="dashboard-top"><section class="continue-card card"><div class="continue-copy"><div class="eyebrow">${icon('book')}${state.completed.length?'CONTINUE YOUR JOURNEY':'YOUR FIRST SMALL STEP'}</div><span class="pill">Chapter ${c.number} · Lesson ${l.id}</span><h2>${esc(l.title)}</h2><p>${esc(l.cards[0].intro.split('. ')[0])}.</p><a class="button dark" href="#lesson/${l.id}" data-start-session>${icon('play')}${state.completed.length||state.lessonSteps[l.id]?'Continue learning':'Start this lesson'}</a></div><div class="continue-visual"><img src="assets/motorway-exit.webp" alt="A motorway exit, with a clearly marked hatched area"><div class="visual-badge">${icon('spark')}One lesson at a time</div><span class="image-credit">From your SourceBook · p. 15</span></div></section><section class="progress-card card"><h3>Your journey so far</h3>${ring(p)}<p>${state.completed.length} of ${lessons.length} lessons complete<br>${state.completed.length?"You’re building a solid foundation.":'Every journey starts with one lesson.'}</p><a href="#progress" class="text-link">View my progress${icon('chevron')}</a></section></div><div class="dashboard-middle"><section class="session-card card"><div class="session-header"><h3>${icon('clock')}Make time for a little win</h3><span class="pill green" id="goal-value">${state.goal} minutes</span></div><p>Choose today’s session length. We’ll give you a gentle break reminder.</p><div><input class="session-range" aria-label="Session length in minutes" type="range" min="5" max="20" step="5" value="${state.goal}" id="session-goal"><div class="range-labels"><span>5 min · quick focus</span><span>20 min · deeper dive</span></div></div></section><section class="quiz-teaser card"><span class="quiz-icon">${icon('quiz')}</span><div><h3>A quick check, without the pressure.</h3><p>${state.mistakes.length?`${state.mistakes.length} questions to revisit. A mistake is just a useful clue.`:'Try a few English questions. Get a clear explanation after every answer.'}</p><a class="text-link" href="#practice">${state.mistakes.length?'Revisit my tricky questions':'Take a practice quiz'}${icon('chevron')}</a></div></section></div><div class="section-head"><div><h2>Your learning path</h2><p>Nine sections. Small lessons. All yours to explore.</p></div><a href="#learn" class="text-link">Explore all lessons${icon('chevron')}</a></div><div class="chapter-grid">${chapters.map(chapterCard).join('')}</div>`, 'home','My dashboard');}
function learn(){return layout(`${intro('Your learning path','Follow the book’s 31 lessons, rewritten into manageable steps.',`<span class="pill green">${state.completed.length}/${lessons.length} complete</span>`)}<section class="progress-overview card">${ring(percentage())}<div><h2>${state.completed.length===31?'You’ve covered the whole course.':'One section at a time.'}</h2><p>Every lesson has three bite-size cards and a quick recall check. Open any section, or pick up where you left off.</p><a href="#lesson/${nextLesson().id}" class="button dark" style="margin-top:18px" data-start-session>${icon('play')}Continue my lesson</a></div></section><div class="chapter-grid">${chapters.map(chapterCard).join('')}</div>`, 'learn','Learning path');}
function chapterView(id){const c=getChapter(id);if(!c)return notFound();const n=c.lessons.filter(x=>state.completed.includes(x)).length;return layout(`${intro(c.title,c.description,`<span class="pill green">${n}/${c.lessons.length} complete</span>`)}<div class="learning-header"><a href="#learn" class="text-link">${icon('back')}All sections</a><button class="button secondary" data-action="chapter-quiz" data-chapter="${c.id}">${icon('quiz')}Practice this section</button></div><div class="history-list">${c.lessons.map(id=>{const l=getLesson(id),done=state.completed.includes(id);return `<a href="#lesson/${id}" class="history-row card" style="text-decoration:none" data-start-session><div style="display:flex;align-items:center;gap:15px"><span class="lesson-status ${done?'done':''}">${done?icon('check'):id}</span><div><h3>${esc(l.title)}</h3><small>3 study cards · about 5 minutes · Book pp. ${l.pages.join('–')}</small></div></div><span class="pill ${done?'green':''}">${done?'Review':state.lessonSteps[id]?'Continue':'Start'}${icon('chevron')}</span></a>`;}).join('')}</div>`, 'learn',c.title);}
function lessonView(id){const l=getLesson(id);if(!l)return notFound();const c=getChapter(l.chapter);let step=state.lessonSteps[l.id]||0;if(step>3)step=0;state.lastLesson=l.id;save();const sc=source(l.source);let body='';
 if(step<3){const a=l.cards[step];body=`<div class="lesson-step-header"><span class="pill">${icon('clock')}One idea · 1–2 minutes</span><div class="steps" aria-label="Card ${step+1} of 3">${[0,1,2].map(x=>`<span class="${x<=step?'done':''}"></span>`).join('')}</div></div><h1 class="lesson-title">${esc(a.title)}</h1><p class="lesson-summary">${esc(a.intro)}</p>${a.image?imageHTML(a.image,assetMeta.find(m=>m.file===a.image)?.kind==='photo'?'photo':'',true):''}<div class="lesson-facts">${a.facts.map((f,i)=>`<div class="fact"><span class="fact-number">${i+1}</span><span>${esc(f)}</span></div>`).join('')}</div><div class="remember">${icon('spark')}<div><strong>Remember this</strong><p>${esc(a.remember)}</p></div></div>${a.more?`<details class="details"><summary>A little more detail</summary><p>${esc(a.more)}</p></details>`:''}<div class="lesson-source">SourceBook pp. ${l.pages.join('–')} · <a href="${esc(sc.url)}" target="_blank" rel="noopener">${esc(sc.publisher)} — current rules</a></div><div class="lesson-bottom"><button class="button ghost" data-action="previous-card" ${step===0?'disabled':''}>${icon('back')}Previous</button><span class="small muted">Card ${step+1} of 3</span><button class="button dark" data-action="next-card">${step===2?'Quick recall check':'Next idea'}</button></div>`;}
 else {if(!check||check.lesson!==l.id){check={lesson:l.id,question:QUESTIONS.filter(q=>q.lesson===l.id)[Math.floor(Math.random()*QUESTIONS.filter(q=>q.lesson===l.id).length)],answer:null};}const q=check.question,correct=check.answer===q.answer;body=`<span class="pill green">${icon('quiz')}Quick recall check</span><h1 class="lesson-title">Let’s make it stick.</h1><p class="lesson-summary">One question. Take your time. You can try again.</p>${q.image?imageHTML(q.image,'',true):''}<h2 style="font-size:1.25rem;line-height:1.55">${esc(q.text)}</h2><div class="choices">${q.options.map((x,i)=>choiceHTML(x,i,check.answer===null?'':i===q.answer?'correct':i===check.answer?'wrong':'',check.answer!==null,'check-answer')).join('')}</div>${check.answer!==null?`<div class="answer-feedback ${correct?'':'wrong'}"><strong>${icon(correct?'check':'leaf')}${correct?'That’s it. You’ve got this.':'A useful thing to remember.'}</strong>${esc(q.explanation)}</div><div class="result-actions"><button class="button secondary" data-action="previous-card">Read the last idea</button><button class="button dark" data-action="${correct?'complete-lesson':'retry-check'}">${correct?'Finish lesson':'Try the check again'}</button></div>`:''}`;}
 return layout(`<div class="learning-header"><div class="left"><a class="icon-button" href="#chapter/${c.id}" aria-label="Back to section">${icon('back')}</a><div class="lesson-path"><span>${c.title}</span><span>/</span><strong>Lesson ${l.id}</strong></div></div><div style="display:flex;gap:8px"><button class="button secondary small" data-action="listen-lesson">${icon(audioPlaying?'stop':'volume')}<span>${audioPlaying?'Stop audio':'Listen'}</span></button><button class="button secondary small focus-toggle" data-action="focus">${icon('focus')}${state.focus?'Exit focus':'Focus mode'}</button></div></div><div class="lesson-layout"><aside class="lesson-list card"><h3>${esc(c.title)}</h3>${c.lessons.map(n=>`<a href="#lesson/${n}" class="${n===l.id?'active':''}" ${n===l.id?'aria-current="page"':''}><span class="lesson-status ${state.completed.includes(n)?'done':''}">${state.completed.includes(n)?icon('check'):n}</span>${esc(getLesson(n).title)}</a>`).join('')}</aside><section class="lesson-panel card">${body}</section></div>`, 'learn',`Lesson ${l.id}`);
}
function choiceHTML(x,i,css='',disabled=false,action='answer'){return `<button class="choice ${css}" data-action="${action}" data-answer="${i}" ${disabled?'disabled':''} aria-pressed="${css==='selected'}"><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${esc(x)}</span>${css==='correct'?icon('check'):''}</button>`;}
function practice(){return layout(`${intro('Practice, then understand.','No timer. Clear English. Explanations that help the rules stick.')}<div class="mode-cards"><section class="mode-card card">${icon('quiz')}<h2>Build your confidence</h2><p>Mix topics or focus on one section. Every answer comes with a reason and a link back to the lesson.</p><a href="#quiz-setup" class="button dark">Choose a quiz</a></section><section class="mode-card card review-card">${icon('refresh')}<h2>Give tricky questions another go</h2><p>${state.mistakes.length?`${state.mistakes.length} questions are waiting for another look. Correct answers remove them from your review list.`:'Your review list is empty. Questions you miss will appear here, ready for another try.'}</p><button class="button secondary" data-action="mistakes-quiz" ${state.mistakes.length?'':'disabled'}>Review ${state.mistakes.length||'my'} questions</button></section></div><div class="section-head"><div><h2>Recent practice</h2><p>Your own progress, without comparing you to anyone else.</p></div></div>${historyHTML('quiz')}`, 'practice','Practice quizzes');}
function quizSetup(){return layout(`${intro('Make this quiz yours.','Pick a section and a length that fits your attention today.')}<section class="quiz-config card"><h2>A small, useful challenge</h2><p class="muted small">Questions are shuffled each time. There’s no pass or fail in practice.</p><form id="quiz-config"><div class="form-grid"><div class="field"><label for="quiz-topic">What would you like to practise?</label><select id="quiz-topic"><option value="all">All nine sections</option>${chapters.map(c=>`<option value="${c.id}">${c.number} · ${c.title}</option>`).join('')}</select></div><div class="field"><label for="quiz-length">How many questions?</label><select id="quiz-length"><option value="5">5 · a quick win</option><option value="10" selected>10 · a focused session</option><option value="20">20 · a deeper check</option></select></div></div><button class="button dark" type="submit">${icon('play')}Start my quiz</button></form></section><p class="legal-foot">These are original study questions based on the book and current rules, rather than questions from the official exam bank.</p>`, 'practice','Quiz setup');}
function historyHTML(mode){const results=state.results.filter(r=>mode==='exam'?r.mode!=='quiz':r.mode==='quiz').slice(0,6);if(!results.length)return `<section class="empty-state card">${icon(mode==='exam'?'headphones':'quiz')}<h3>Your first result will go here.</h3><p>${mode==='exam'?'Use the simulator when you’re ready to practise the exam rhythm.':'Start with a short quiz. You do not have to know everything first.'}</p></section>`;return `<div class="history-list">${results.map(r=>`<div class="history-row card"><div><strong>${r.mode==='quiz'?'English practice':r.mode==='text-exam'?'Timed text simulation':'Timed audio simulation'}</strong><small>${new Date(r.date).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})} · ${r.total} questions · ${r.correct} correct</small></div><span class="history-score">${r.score}/${r.total}${r.mode!=='quiz'?`<small>${r.score>=41?'Pass level reached':'Keep practising'}</small>`:''}</span></div>`).join('')}</div>`;}
function examSetup(){return layout(`${intro('Practise the exam rhythm.','Dutch first. English translation. Then 15 seconds to decide.')}<div class="exam-info"><section class="exam-info-main card"><span class="pill blue">${icon('headphones')}Flanders · translated audio practice</span><h2 style="margin-top:18px">A realistic pace, in your own space.</h2><p class="muted">The official Flemish exam has 50 questions. Aim for at least 41/50, and be especially careful with serious offences and speed limits.</p><div class="exam-stats"><div class="exam-stat"><strong>50</strong><span>questions</span></div><div class="exam-stat"><strong>15 s</strong><span>after narration</span></div><div class="exam-stat"><strong>41/50</strong><span>pass threshold</span></div></div><ul class="exam-rules"><li>In exam-style mode, the screen shows Dutch. The question and options are read in Dutch, then English. The countdown starts after the audio ends.</li><li>A normal wrong or unanswered question costs 1 point. A marked 3rd/4th-degree offence or maximum-speed violation costs 5.</li><li>There is one answer per question. Explanations appear at the end, so you can practise staying in the flow.</li><li>These are original practice questions. Browser voices approximate the translated exam; they are not official recordings.</li></ul><form id="exam-config"><div class="form-grid"><div class="field"><label for="exam-audio">Audio mode</label><select id="exam-audio"><option value="nl-en" ${state.voiceMode==='nl-en'?'selected':''}>Dutch, then English · exam-style</option><option value="en" ${state.voiceMode==='en'?'selected':''}>English only · practice</option><option value="text">Timed English text · without audio</option></select></div><div class="field"><label>Check your sound</label><button class="button secondary" type="button" data-action="test-audio">${icon('volume')}Test Dutch & English</button></div></div><p id="audio-test-status" class="settings-note" role="status">${voiceSupportText()}</p><button class="button dark" type="submit" style="margin-top:19px">${icon('play')}Start 50-question simulation</button></form></section><aside class="exam-side card"><span class="eyebrow">YOUR LOCAL EXAM</span><h3>Geel · near Turnhout</h3><p>Autoveiligheid’s driving-test centre is at Lammerdries 7, 2440 Geel. Turnhout is listed as a vehicle-inspection station, rather than a driving-test centre.</p><p>Book the regular theory appointment online with English audio translation, and tell the desk your chosen language when you arrive.</p><p>The real screen stays in Dutch. Audio reads the question and options in Dutch, then English. After the reading, you have 15 seconds to answer.</p><a href="${esc(source('centres').url)}" target="_blank" rel="noopener">Check booking & language support</a><p class="settings-note">Minimum age: 17. Bring your original accepted identity document. Current listed fee: €19 + €43 for audio translation. A pass is valid for 3 years.</p><p class="settings-note">After two failed attempts, 12 hours of recognised theory lessons are required before the third attempt. A slower session is available for eligible candidates under the official conditions; ask the centre about the required supporting evidence.</p><a href="${esc(source('exam').url)}" target="_blank" rel="noopener">Read the official Flemish exam rules</a></aside></div><div class="section-head"><h2>Your simulations</h2></div>${historyHTML('exam')}`, 'exam','Exam simulator');}
function voiceSupportText(){if(!('speechSynthesis' in window))return 'This browser does not support speech. Choose the timed text mode.';const v=speechSynthesis.getVoices();const nl=v.some(x=>x.lang.startsWith('nl')),en=v.some(x=>x.lang.startsWith('en'));return nl&&en?'Dutch and English voices are available. Use the sound test before you start.':'Voice availability depends on your browser and device. Test both languages; timed text is available if audio fails.';}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function startQuiz(mode,pool,count,audio='nl-en'){
 stopAudio();stopTimer();quiz={mode,questions:shuffle(pool).slice(0,count),index:0,answers:[],selected:null,revealed:false,started:Date.now(),audio,phase:'ready',remaining:15,deadline:null,finished:false,allowAdvance:false};
 if(!quiz.questions.length){toast('No questions are available for that selection.');return;}
 location.hash='quiz'; if(route()==='quiz')render();if(mode!=='quiz'&&audio==='text'){quiz.phase='answering';render();beginCountdown();}
}
function quizView(){if(!quiz)return layout(`${intro('Ready for a new practice round?','Your completed results and lesson progress are saved.')}<a class="button dark" href="#practice">Choose a practice quiz</a>`, 'practice','Practice');if(quiz.finished)return quizResults();const q=quiz.questions[quiz.index],exam=quiz.mode!=='quiz',last=quiz.index===quiz.questions.length-1;
 const displayText=exam&&quiz.audio==='nl-en'?q.nl:q.text,displayOptions=exam&&quiz.audio==='nl-en'?q.nlOptions:q.options;
 const chosen=quiz.selected,answerClass=i=>!exam&&quiz.revealed?(i===q.answer?'correct':i===chosen?'wrong':''):i===chosen?'selected':'';
 return layout(`<div class="quiz-layout"><div class="quiz-top"><div><span class="eyebrow">${exam?'EXAM SIMULATION':'ENGLISH PRACTICE'}</span><strong>Question ${quiz.index+1} of ${quiz.questions.length}</strong>${track(Math.round(quiz.index/quiz.questions.length*100))}</div>${exam?`<div><span class="timer ${quiz.phase==='narrating'||quiz.phase==='ready'||quiz.phase==='blocked'?'waiting':quiz.remaining<=5?'urgent':''}" id="exam-timer" aria-label="Answer time">${icon('clock')}<span>${quiz.phase==='narrating'?'Listening':quiz.phase==='blocked'?'Audio paused':quiz.phase==='ready'?'Ready':`${quiz.remaining}s`}</span></span></div>`:''}<button class="button ghost" data-action="exit-quiz">Exit</button></div><section class="quiz-question card">${exam?`<div class="audio-status" id="audio-status">${icon('headphones')}<span id="audio-status-text">${quiz.phase==='ready'?'Press play when you’re ready.':quiz.phase==='narrating'?'Listen to the question and options.':quiz.phase==='blocked'?'Audio could not finish. Try again or use timed text.':'Choose and confirm your answer.'}</span>${quiz.phase==='ready'||quiz.phase==='blocked'?`<button class="text-link" data-action="begin-audio">${quiz.phase==='blocked'?'Retry audio':'Play question'}</button>`:''}${quiz.phase!=='answering'?'<button class="text-link" data-action="use-text">Use timed text</button>':''}</div><div class="timer-track"><span id="timer-bar" style="width:${quiz.phase==='answering'?quiz.remaining/15*100:100}%"></span></div>`:`<span class="pill">${esc(getChapter(getLesson(q.lesson).chapter).title)}</span>`}<h2 lang="${exam&&quiz.audio==='nl-en'?'nl':'en'}">${esc(displayText)}</h2>${q.image?`<div class="question-image"><img src="assets/${q.image}" alt="${esc(assetMeta.find(x=>x.file===q.image)?.label||'Road situation')}" loading="eager"></div>`:''}<div class="choices" lang="${exam&&quiz.audio==='nl-en'?'nl':'en'}">${displayOptions.map((x,i)=>choiceHTML(x,i,answerClass(i),quiz.revealed||exam&&quiz.phase!=='answering')).join('')}</div>${!exam&&quiz.revealed?`<div class="answer-feedback ${chosen===q.answer?'':'wrong'}"><strong>${icon(chosen===q.answer?'check':'leaf')}${chosen===q.answer?'Correct. Here’s why.':'Good to catch this here.'}</strong>${esc(q.explanation)}<a href="#lesson/${q.lesson}" data-action="review-lesson" data-lesson="${q.lesson}">Review: ${esc(getLesson(q.lesson).title)}</a></div>`:''}<div class="question-footer">${exam?`<button class="button dark exam-submit" data-action="confirm-answer" ${chosen===null||quiz.phase!=='answering'?'disabled':''}>Confirm answer</button>`:`<span class="small">${quiz.revealed?'Understanding matters more than speed.':'Take your time. There’s no countdown.'}</span><button class="button dark" data-action="${quiz.revealed?'next-question':'check-quiz-answer'}" ${chosen===null&&!quiz.revealed?'disabled':''}>${quiz.revealed?(last?'See my result':'Next question'):'Check answer'}</button>`}</div></section><p class="legal-foot">${exam?'The timer begins after narration finishes. Results and explanations follow all 50 questions.':'Original study questions · English explanations · Your tricky questions are saved for review.'}</p></div>`,exam?'exam':'practice',exam?'Exam simulation':'English practice');
}
function recordAnswer(answer){const q=quiz.questions[quiz.index],correct=answer===q.answer;quiz.answers.push({id:q.id,answer,correct,penalty:correct?0:quiz.mode==='quiz'?1:q.major?5:1});updateMistake(q,correct);save();}
function updateMistake(q,correct){if(correct){state.correctCounts[q.id]=(state.correctCounts[q.id]||0)+1;state.mistakes=state.mistakes.filter(id=>id!==q.id);}else if(!state.mistakes.includes(q.id))state.mistakes.push(q.id);}
function advanceQuestion(){stopAudio();stopTimer();if(quiz.index+1>=quiz.questions.length){finishQuiz();return;}quiz.index++;quiz.selected=null;quiz.revealed=false;quiz.phase=quiz.mode==='quiz'?'ready':quiz.audio==='text'?'answering':'ready';quiz.remaining=15;quiz.deadline=null;render();if(quiz.mode!=='quiz'){if(quiz.audio==='text')beginCountdown();else beginNarration();}window.scrollTo({top:0,behavior:'instant'});}
function finishQuiz(){stopAudio();stopTimer();quiz.finished=true;quiz.phase='finished';const correct=quiz.answers.filter(x=>x.correct).length;const score=Math.max(0,quiz.questions.length-quiz.answers.reduce((a,x)=>a+x.penalty,0));const r={mode:quiz.mode==='quiz'?'quiz':quiz.audio==='text'?'text-exam':'exam',date:new Date().toISOString(),score,total:quiz.questions.length,correct};state.results.unshift(r);state.results=state.results.slice(0,100);save();render();}
function quizResults(){const exam=quiz.mode!=='quiz',correct=quiz.answers.filter(x=>x.correct).length,score=Math.max(0,quiz.questions.length-quiz.answers.reduce((a,x)=>a+x.penalty,0)),wrong=quiz.answers.filter(x=>!x.correct);return layout(`<section class="result-card card"><div class="result-symbol">${icon(exam&&score>=41?'trophy':wrong.length?'leaf':'spark')}</div><span class="pill ${exam&&score<41?'orange':'green'}">${exam?(score>=41?'Pass level reached':'Another step in your preparation'):'Practice complete'}</span><h1 style="margin-top:17px">${exam?(score>=41?'A confident practice run.':'You know what to practise next.'):wrong.length?'Every check helps it stick.':'That was a clean run.'}</h1><div class="result-score">${score}<span> / ${quiz.questions.length}</span></div><p>${correct} correct answers · ${wrong.length} to revisit${exam?`<br>${quiz.answers.filter(a=>!a.correct&&a.penalty===5).length} five-point mistakes · pass threshold 41/50`:''}</p><div class="result-actions"><button class="button dark" data-action="retry-quiz">${icon('refresh')}Try another round</button>${wrong.length?'<button class="button secondary" data-action="result-review">Practise these mistakes</button>':''}<a class="button secondary" href="#progress">My progress</a></div>${wrong.length?`<div class="section-head"><h2>Make sense of the tricky ones</h2></div><div class="review-list">${wrong.map(a=>{const q=QUESTIONS.find(q=>q.id===a.id);return `<article class="review-item"><span class="pill ${exam&&q.major?'orange':''}">${a.answer===null?'No answer in time':'To revisit'}${exam&&q.major?' · −5 points':''}</span><h3>${esc(q.text)}</h3><p>Your answer: ${a.answer===null?'No answer':esc(q.options[a.answer])}</p><p><strong>Correct: ${esc(q.options[q.answer])}</strong></p><p style="margin-top:7px">${esc(q.explanation)}</p>${exam&&q.major?`<p style="margin-top:7px"><strong>Five-point reason:</strong> ${esc(q.severityReason)} · <a href="${esc(source('degrees').url)}" target="_blank" rel="noopener">Offence classification</a></p>`:''}<a class="text-link" href="#lesson/${q.lesson}">Review lesson ${q.lesson}${icon('chevron')}</a></article>`;}).join('')}</div>`:''}</section>`,exam?'exam':'practice','Your result');}
function progressView(){return layout(`${intro('Look how far you’ve come.','Lesson completion, practice results, and a clear next step.')}<section class="progress-overview card">${ring(percentage())}<div><h2>${state.completed.length} lessons complete. ${lessons.length-state.completed.length} to explore.</h2><p>Lesson progress measures the cards you’ve studied and checked. Quiz scores help you decide what to revisit; they do not automatically mark a lesson complete.</p><a class="button dark" href="#lesson/${nextLesson().id}" style="margin-top:17px" data-start-session>Continue my learning</a></div></section>${chapters.map(c=>{const n=c.lessons.filter(id=>state.completed.includes(id)).length;return `<section class="chapter-progress card"><div><h3>${c.number} · ${esc(c.title)}</h3><p>${n} of ${c.lessons.length} lessons complete</p></div>${track(Math.round(n/c.lessons.length*100))}<a class="text-link" href="#chapter/${c.id}">${n===c.lessons.length?'Review':'Continue'}${icon('chevron')}</a></section>`;}).join('')}<div class="section-head"><h2>Exam practice</h2></div>${historyHTML('exam')}<div class="section-head"><h2>English quizzes</h2></div>${historyHTML('quiz')}<section class="storage-card card"><div><h3>${icon('lock')}Your progress stays with you</h3><p>Saved locally in this browser on this device. Clearing browser data removes it. Export a backup if you want to keep it or transfer it to another browser.</p></div><div class="storage-actions"><button class="button secondary" data-action="export">${icon('download')}Export</button><button class="button secondary" data-action="import">${icon('upload')}Import</button><button class="button ghost" data-action="reset">Reset</button><input type="file" id="import-file" accept="application/json,.json" hidden></div></section>`, 'progress','My progress');}
function sourcesView(){return layout(`${intro('Your book, brought up to date.','A clear trail from the SourceBook to current official guidance.',`<span class="pill green">Checked 1 Oct 2026</span>`)}<section class="source-intro card"><p><strong>Your course is based on all 31 lessons in the 239-page SourceBook.</strong> Its PDF metadata dates to 27 August 2022. The English explanations are rewritten for focused study, with 35 images extracted from the book and 105 original bilingual questions.</p></section><div class="source-grid"><section class="source-card card"><span class="pill">YOUR ORIGINAL REFERENCE</span><h3>SourceBook.pdf</h3><p>Page references use the PDF’s 1-based page numbers. Every extracted image retains its page credit. The book’s illustrations come from the reference material; older wording is checked against current rules.</p><a href="https://github.com/molntam/BelgianDrivingLicenseTheoryAPP/blob/main/source/SourceBook.pdf" target="_blank" rel="noopener">Open your SourceBook on GitHub</a></section>${sources.map(s=>`<section class="source-card card"><span class="pill">${esc(s.publisher)}</span><h3>${esc(s.title)}</h3><p>${esc(s.note)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener">Read the source${icon('chevron')}</a></section>`).join('')}</div><section class="updates-list card"><h2>What changed from the book?</h2><ul><li><strong>Cycle zones:</strong> current cycle-zone rules continue until an end sign. The book’s old “bicycle street ends at the next junction” shortcut is removed.</li><li><strong>Regional speeds:</strong> the book’s generic 50 km/h built-up summary is corrected with Flanders/Wallonia 50 and Brussels built-up areas normally 30. On ordinary roads outside town, Flanders and Brussels normally use 70, Wallonia normally 90.</li><li><strong>Phones:</strong> the current rule covers holding, using or manipulating a mobile device with a screen when it is not secured in a suitable holder, including while waiting at traffic lights.</li><li><strong>Tyres:</strong> the book’s mileage-only replacement statement is removed. Wear, damage, age and manufacturer guidance matter; cold pressures come from the vehicle specification.</li><li><strong>Stopping distances:</strong> fixed charts are treated as examples, not guaranteed stopping distances. Reaction, grip, weather and tyres all affect a real stop.</li><li><strong>Electric scooters:</strong> current cyclist treatment and the September 2026 helmet requirement for devices designed above 20 km/h are added.</li><li><strong>Exam practice:</strong> current Flemish scoring, language arrangements and answer timing come from official exam guidance, rather than the book.</li><li><strong>Future road code:</strong> the new public-road code is scheduled for 1 June 2027. This course uses rules in force on the checked date, and keeps future rules separate.</li></ul></section><section class="updates-list card"><h2>About the simulator</h2><p class="muted small" style="margin-top:13px">The questions and Dutch/English scripts were written for this course. Your device supplies the voices; pronunciation and reading speed vary. The timer starts after narration. The official question bank, recordings, booking and accommodations remain with the exam operator.</p><p class="muted small" style="margin-top:12px">This is a checked snapshot, not a live legal update service. If your exam is after the announced new-code date, recheck the official sources before studying.</p></section>`, 'sources','Book & sources');}
function notFound(){return layout(`${intro('Let’s get you back on the road.','This lesson or section could not be found.')}<a class="button dark" href="#learn">Open the learning path</a>`, 'learn','Learning path');}
function render(){const r=route();let html;if(r==='home')html=home();else if(r==='learn')html=learn();else if(r.startsWith('chapter/'))html=chapterView(r.split('/')[1]);else if(r.startsWith('lesson/'))html=lessonView(r.split('/')[1]);else if(r==='practice')html=practice();else if(r==='quiz-setup')html=quizSetup();else if(r==='exam')html=examSetup();else if(r==='quiz')html=quizView();else if(r==='progress')html=progressView();else if(r==='sources')html=sourcesView();else html=notFound();$('#app').innerHTML=html;document.title=`${({'home':'My dashboard','learn':'Learning path','practice':'Practice','exam':'Exam simulator','progress':'My progress','sources':'Book & sources'})[r]||'Learn'} · Drive B`;bind();}
function navigate(hash){if(location.hash===hash)render();else location.hash=hash;}
function openModal(html){stopAudio();const lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1">${html}</section></div>`;$('.modal').focus();const trap=e=>{if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const fs=$$('button,a,input,select,[tabindex="0"]',$('.modal')).filter(x=>!x.disabled);if(!fs.length)return;if(e.shiftKey&&document.activeElement===fs[0]){e.preventDefault();fs.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===fs.at(-1)){e.preventDefault();fs[0].focus();}}};document.addEventListener('keydown',trap);openModal.cleanup=()=>{document.removeEventListener('keydown',trap);if(lastFocus&&document.contains(lastFocus))lastFocus.focus();};$$('[data-close-modal]').forEach(b=>b.onclick=closeModal);}
function closeModal(){openModal.cleanup?.();$('#modal-root').innerHTML='';}
function settings(){openModal(`<button class="modal-close" data-close-modal aria-label="Close settings">${icon('close')}</button><h2 id="modal-title">Your study settings</h2><p>The course defaults to your Flemish exam. Regional comparisons remain in the lessons.</p><div class="field"><label for="setting-region">Your exam region</label><select id="setting-region">${['Flanders','Brussels','Wallonia'].map(x=>`<option ${state.region===x?'selected':''}>${x}</option>`).join('')}</select></div><p class="settings-note">The exam simulator follows the Flemish scoring and booking format. Changing this label does not convert it into another region’s exam.</p><div class="modal-actions"><button class="button dark" id="save-settings">Save settings</button></div>`);$('#save-settings').onclick=()=>{state.region=$('#setting-region').value;save();closeModal();render();};}
function exitQuiz(after){if(!quiz||quiz.finished){after?.();return;}if(quiz.phase==='narrating'){stopAudio();quiz.phase='blocked';render();}openModal(`<h2 id="modal-title">Finish this round early?</h2><p>Your lesson progress and answers already reviewed stay saved. This unfinished quiz will end without a result.</p><div class="modal-actions"><button class="button secondary" data-close-modal>Stay in this round</button><button class="button dark" id="confirm-exit">Leave this round</button></div>`);$('#confirm-exit').onclick=()=>{stopTimer();stopAudio();quiz=null;closeModal();after?after():navigate('#practice');};}
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`drive-b-progress-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Your progress backup is ready.');}
function bind(){
 $$('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{if(a.dataset.action)return;if(quiz&&!quiz.finished&&route()==='quiz'&&a.hash!=='#quiz'){e.preventDefault();exitQuiz(()=>navigate(a.hash));return;}if(a.hasAttribute('data-start-session'))startSession();document.body.classList.remove('menu-open');}));
 const range=$('#session-goal');if(range)range.oninput=()=>{state.goal=Number(range.value);$('#goal-value').textContent=`${state.goal} minutes`;save();};
 const qc=$('#quiz-config');if(qc)qc.onsubmit=e=>{e.preventDefault();const c=$('#quiz-topic').value;const pool=c==='all'?QUESTIONS:QUESTIONS.filter(q=>getLesson(q.lesson).chapter===c);startQuiz('quiz',pool,Number($('#quiz-length').value));};
 const ec=$('#exam-config');if(ec)ec.onsubmit=e=>{e.preventDefault();const mode=$('#exam-audio').value;if(mode!=='text'&&!('speechSynthesis' in window)){toast('Speech is unavailable. Choose timed English text.');return;}state.voiceMode=mode==='text'?'nl-en':mode;save();startQuiz('exam',examPool(),50,mode);};
 $$('[data-action]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();action(b.dataset.action,b);}));
 const f=$('#import-file');if(f)f.onchange=importProgress;
}
function examPool(){// Keep all nine sections represented, then shuffle the remaining slots.
 const chosen=[];for(const c of chapters){const pool=shuffle(QUESTIONS.filter(q=>getLesson(q.lesson).chapter===c.id));chosen.push(...pool.slice(0,Math.min(4,pool.length)));}const ids=new Set(chosen.map(q=>q.id));return [...chosen,...shuffle(QUESTIONS.filter(q=>!ids.has(q.id))).slice(0,50-chosen.length)];}
function startSession(){if(!session||Date.now()-session.start>session.duration){session={start:Date.now(),duration:state.goal*60000};breakDismissed=false;}}
function action(a,b){
 if(a==='menu'){document.body.classList.toggle('menu-open');b.setAttribute('aria-expanded',document.body.classList.contains('menu-open'));}
 else if(a==='settings')settings();
 else if(a==='dismiss-break'){breakDismissed=true;render();}
 else if(a==='focus'){state.focus=!state.focus;save();render();}
 else if(a==='next-card'||a==='previous-card'){stopAudio();const l=getLesson(route().split('/')[1]);state.lessonSteps[l.id]=Math.max(0,Math.min(3,(state.lessonSteps[l.id]||0)+(a==='next-card'?1:-1)));if(a==='previous-card')check=null;save();render();window.scrollTo({top:0,behavior:'instant'});}
 else if(a==='check-answer'){if(check.answer!==null)return;check.answer=Number(b.dataset.answer);updateMistake(check.question,check.answer===check.question.answer);save();render();}
 else if(a==='retry-check'){check.answer=null;render();}
 else if(a==='complete-lesson'){const l=getLesson(route().split('/')[1]);if(!state.completed.includes(l.id))state.completed.push(l.id);state.lessonSteps[l.id]=0;save();stopAudio();const next=lessons.find(x=>x.id>l.id&&!state.completed.includes(x.id))||lessons.find(x=>!state.completed.includes(x.id));openModal(`<h2 id="modal-title">${icon('spark')}One more lesson, in your pocket.</h2><p>You’ve completed <strong>${esc(l.title)}</strong>. That’s ${state.completed.length} of ${lessons.length} lessons. A break is a good next step too.</p><div class="modal-actions"><a class="button secondary" href="#home" id="complete-home">Take a break</a>${next?`<a class="button dark" href="#lesson/${next.id}" id="complete-next">Next lesson</a>`:'<a class="button dark" href="#exam" id="complete-next">Try the simulator</a>'}</div>`);$('#complete-home').onclick=()=>{session=null;closeModal();};$('#complete-next').onclick=()=>{closeModal();};render();}
 else if(a==='listen-lesson'){if(audioPlaying){stopAudio();render();return;}const l=getLesson(route().split('/')[1]),st=state.lessonSteps[l.id]||0;const c=l.cards[Math.min(st,2)];audioPlaying=true;speakSegments([{text:[c.title,c.intro,...c.facts,'Remember this.',c.remember].join(' '),lang:'en'}],()=>{audioPlaying=false;if(route().startsWith('lesson/'))render();},()=>{audioPlaying=false;toast('Audio is unavailable on this device. You can keep reading.');render();});render();}
 else if(a==='chapter-quiz'){const pool=QUESTIONS.filter(q=>getLesson(q.lesson).chapter===b.dataset.chapter);startQuiz('quiz',pool,Math.min(10,pool.length));}
 else if(a==='mistakes-quiz')startQuiz('quiz',QUESTIONS.filter(q=>state.mistakes.includes(q.id)),Math.min(20,state.mistakes.length));
 else if(a==='answer'){if(!quiz||quiz.finished||quiz.revealed||quiz.mode!=='quiz'&&quiz.phase!=='answering')return;quiz.selected=Number(b.dataset.answer);$$('.choice').forEach((x,i)=>{x.classList.toggle('selected',i===quiz.selected);x.setAttribute('aria-pressed',String(i===quiz.selected));});const btn=$('[data-action="check-quiz-answer"],[data-action="confirm-answer"]');if(btn)btn.disabled=false;}
 else if(a==='check-quiz-answer'){if(quiz.selected===null)return;recordAnswer(quiz.selected);quiz.revealed=true;render();}
 else if(a==='next-question')advanceQuestion();
 else if(a==='confirm-answer'){if(quiz.phase!=='answering'||quiz.selected===null)return;stopTimer();recordAnswer(quiz.selected);advanceQuestion();}
 else if(a==='exit-quiz')exitQuiz();
 else if(a==='review-lesson'){exitQuiz(()=>navigate(`#lesson/${b.dataset.lesson}`));}
 else if(a==='retry-quiz'){const q=quiz;startQuiz(q.mode,q.mode==='quiz'?QUESTIONS:examPool(),q.questions.length,q.audio);}
 else if(a==='result-review'){const ids=quiz.answers.filter(x=>!x.correct).map(x=>x.id);startQuiz('quiz',QUESTIONS.filter(x=>ids.includes(x.id)),ids.length);}
 else if(a==='begin-audio')beginNarration();
 else if(a==='use-text'){stopAudio();quiz.audio='text';quiz.phase='answering';render();beginCountdown();}
 else if(a==='test-audio'){const status=$('#audio-test-status');if(status)status.textContent='Playing Dutch first, then English…';speakSegments([{text:'Dit is een geluidstest. Je hoort de vraag eerst in het Nederlands.',lang:'nl'},{text:'This is an audio test. You will hear the English translation next, then your answer timer begins.',lang:'en'}],()=>{if(status)status.textContent='Test complete. If both languages sounded correct, you are ready.';},()=>{if(status)status.textContent='Audio did not finish. Check your browser voices or use the timed text mode.';});}
 else if(a==='export')exportProgress();
 else if(a==='import')$('#import-file').click();
 else if(a==='reset'){openModal(`<h2 id="modal-title">Start your progress again?</h2><p>This clears completed lessons, quiz results and your review list in this browser. Export a backup first if you want to keep them.</p><div class="modal-actions"><button class="button secondary" data-close-modal>Keep my progress</button><button class="button danger" id="confirm-reset">Reset my progress</button></div>`);$('#confirm-reset').onclick=()=>{state=defaults();check=null;session=null;save();closeModal();render();toast('Your learning path is ready for a fresh start.');};}
}
function importProgress(e){const file=e.target.files?.[0];if(!file)return;if(file.size>500000){toast('This backup is too large. Choose a Drive B progress file.');return;}const reader=new FileReader();reader.onload=()=>{let incoming;try{incoming=JSON.parse(reader.result);if(!validProgress(incoming))throw Error();}catch(e){toast('This is not a valid Drive B progress backup. Your progress is unchanged.');return;}openModal(`<h2 id="modal-title">Restore this progress?</h2><p>This backup contains ${incoming.completed.length} completed lessons and ${incoming.results.length} results. It will replace the progress in this browser.</p><div class="modal-actions"><button class="button secondary" data-close-modal>Cancel</button><button class="button dark" id="confirm-import">Restore backup</button></div>`);$('#confirm-import').onclick=()=>{state={...defaults(),...incoming,completed:[...new Set(incoming.completed)]};check=null;save();closeModal();render();toast('Your progress has been restored.');};};reader.onerror=()=>toast('The file could not be read. Your progress is unchanged.');reader.readAsText(file);e.target.value='';}
function speakSegments(segments,done,failed){stopAudio();if(!('speechSynthesis' in window)){failed();return;}const token=audioToken;audioPlaying=true;let index=0;const play=()=>{if(token!==audioToken)return;if(index>=segments.length){audioPlaying=false;done();return;}const s=segments[index++],utterance=new SpeechSynthesisUtterance(s.text),voices=speechSynthesis.getVoices();utterance.lang=s.lang==='nl'?'nl-BE':s.lang==='fr'?'fr-BE':'en-GB';const pref=voices.find(v=>v.lang===utterance.lang)||voices.find(v=>v.lang.startsWith(s.lang));if(pref)utterance.voice=pref;else if(voices.length&&s.lang==='nl'){audioPlaying=false;failed();return;}utterance.rate=.95;utterance.onend=()=>{clearTimeout(audioWatchdog);if(token===audioToken)play();};utterance.onerror=()=>{clearTimeout(audioWatchdog);if(token===audioToken){audioPlaying=false;failed();}};activeUtterance=utterance;audioWatchdog=setTimeout(()=>{if(token!==audioToken)return;stopAudio();failed();},Math.max(25000,s.text.length*180));speechSynthesis.speak(utterance);};play();}
function beginNarration(){if(!quiz||quiz.finished)return;if(quiz.audio==='text'){quiz.phase='answering';render();beginCountdown();return;}stopTimer();quiz.phase='narrating';quiz.selected=null;render();const q=quiz.questions[quiz.index],seq=[];if(quiz.audio==='nl-en')seq.push({lang:'nl',text:`${q.nl} ${q.nlOptions.map((o,i)=>`${String.fromCharCode(65+i)}. ${o}.`).join(' ')}`});seq.push({lang:'en',text:`${q.text} ${q.options.map((o,i)=>`${String.fromCharCode(65+i)}. ${o}.`).join(' ')}`});speakSegments(seq,()=>{if(!quiz||quiz.finished)return;quiz.phase='answering';render();beginCountdown();},()=>{if(!quiz||quiz.finished)return;quiz.phase='blocked';render();toast('Audio could not finish. Retry it or choose timed text.');});}
function beginCountdown(){if(!quiz||quiz.finished)return;stopTimer();quiz.remaining=15;quiz.deadline=Date.now()+15000;quiz.phase='answering';if($('#exam-timer')){$('#exam-timer').className='timer';$('#exam-timer span').textContent='15s';}const tick=()=>{if(!quiz||quiz.finished||quiz.phase!=='answering'){stopTimer();return;}quiz.remaining=Math.max(0,Math.ceil((quiz.deadline-Date.now())/1000));const el=$('#exam-timer');if(el){el.className=`timer ${quiz.remaining<=5?'urgent':''}`;$('span',el).textContent=`${quiz.remaining}s`;}const bar=$('#timer-bar');if(bar)bar.style.width=`${quiz.remaining/15*100}%`;if(quiz.remaining===0){stopTimer();recordAnswer(null);advanceQuestion();}};tick();timer=setInterval(tick,150);}
window.addEventListener('hashchange',()=>{document.body.classList.remove('menu-open');if(route()!=='quiz'){stopAudio();if(quiz&&!quiz.finished){stopTimer();quiz=null;toast('The unfinished round ended. Your reviewed answers and lessons are saved.');}}render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('beforeunload',e=>{if(quiz&&!quiz.finished){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',e=>{if($('#modal-root').children.length)return;if(route()==='quiz'&&quiz&&!quiz.finished&&['a','b','c'].includes(e.key.toLowerCase())&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){const i=e.key.toLowerCase().charCodeAt(0)-97;const b=$(`[data-action="answer"][data-answer="${i}"]`);if(b&&!b.disabled)b.click();}});
setInterval(()=>{if(session&&!breakDismissed&&Date.now()-session.start>=session.duration&&route().startsWith('lesson/')&&!$('.break-banner'))render();},15000);
if('speechSynthesis' in window)speechSynthesis.addEventListener('voiceschanged',()=>{const el=$('#audio-test-status');if(el&&!audioPlaying)el.textContent=voiceSupportText();});
// Feature-detected WebMCP actions use exactly the same navigation and state as the UI.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=(tool)=>Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});register({name:'read_learning_progress',title:'Read learning progress',description:'Read completed lessons and recent quiz results without changing progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({completedLessons:state.completed,totalLessons:lessons.length,percentage:percentage(),nextLesson:nextLesson().id,recentResults:state.results.slice(0,5)})});register({name:'open_driving_lesson',title:'Open a driving lesson',description:'Open a lesson for study. This does not mark it complete.',inputSchema:{type:'object',properties:{lessonId:{type:'integer',minimum:1,maximum:31}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||!Number.isInteger(input.lessonId)||!getLesson(input.lessonId))throw new Error('Choose a lesson ID from 1 to 31.');if(quiz&&!quiz.finished)throw new Error('Finish or leave the current quiz first.');navigate(`#lesson/${input.lessonId}`);await new Promise(r=>setTimeout(r,30));return {lessonId:input.lessonId,title:getLesson(input.lessonId).title,completed:state.completed.includes(input.lessonId)};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
render();
})();
